pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 initialFunds, uint256 sendAmount, uint8 sendTargetId) public {
        // Bound sendAmount to something reasonable and ensure it does not exceed initialFunds
        initialFunds = bound(initialFunds, 0, 100 ether);
        sendAmount = bound(sendAmount, 0, initialFunds);
        // Create an adversarial target that fails on call, preventing Ether from leaving the contract
        // The reference ensures that sendMoney to a failing target does not change the balance,
        // so only the owner can withdraw. The mutant allows anyone to withdrawAll.
        address target = address(new FailingTarget());
        // Deploy the helper with a deterministic address based on fuzz input to vary the target
        // but ensure it always fails.

        // Fund the contract
        vm.deal(address(this), initialFunds);
        (bool sent,) = address(c).call{value: initialFunds}("");
        require(sent, "funding failed");

        uint256 balanceBefore = address(c).balance;

        // Attacker (non-owner) tries to call sendMoney to the failing target
        vm.prank(address(0xdead));
        try c.sendMoney(target, sendAmount, "") returns (bool success) {
            // sendMoney should revert because the target fails
            // The bug allows withdrawAll by anyone, but sendMoney itself still reverts on failed calls.
            // The difference is that after this, the attacker can call withdrawAll.
            // So we need to check if the balance changes after the attacker tries to withdraw.
            // Actually, sendMoney reverts in both versions, so we need to test the withdrawAll path.
            // We'll test: after a failed sendMoney by non-owner, can the attacker drain the contract?
        } catch {}

        // Now attacker tries to withdrawAll
        vm.prank(address(0xdead));
        try c.withdrawAll() {} catch {}

        uint256 balanceAfter = address(c).balance;

        // The invariant: if sendMoney failed (and no other owner-initiated withdrawal occurred),
        // the balance should remain unchanged because only the owner can withdraw funds.
        // The reference satisfies this; the mutant allows the attacker to drain the contract,
        // so balanceAfter will be 0 (or less).
        assertTrue(balanceAfter == balanceBefore);
    }
}

contract FailingTarget {
    fallback() external payable {
        revert("failing target");
    }
}

